class Solution {
    public boolean repeatedSubstringPattern(String s) {
        String doubled = s + s;
        String interior = doubled.substring(1, doubled.length() - 1);
        return interior.contains(s);
    }
}

class Solution {
    public boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        for (int len = 1; len * len <= n; len++) {
            if (n % len != 0) {
                continue;
            }
            if (len < n && matchesPeriod(s, len)) {
                return true;
            }
            int other = n / len;
            if (other < n && other != len && matchesPeriod(s, other)) {
                return true;
            }
        }
        return false;
    }

    private boolean matchesPeriod(String s, int period) {
        for (int i = period; i < s.length(); i++) {
            if (s.charAt(i) != s.charAt(i % period)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        int[] lps = new int[n];
        for (int i = 1; i < n; i++) {
            int j = lps[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = lps[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                j++;
            }
            lps[i] = j;
        }

        int border = lps[n - 1];
        int period = n - border;
        return border > 0 && n % period == 0;
    }
}

class Solution {
    public boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        int[] z = new int[n];
        int left = 0;
        int right = 0;
        for (int i = 1; i < n; i++) {
            if (i <= right) {
                z[i] = Math.min(right - i + 1, z[i - left]);
            }
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) {
                z[i]++;
            }
            if (i + z[i] - 1 > right) {
                left = i;
                right = i + z[i] - 1;
            }
        }

        for (int period = 1; period <= n / 2; period++) {
            if (n % period == 0 && z[period] >= n - period) {
                return true;
            }
        }
        return false;
    }
}
